-- ----------------------------
-- Table structure for tb_core_role_menu
-- ----------------------------
DROP TABLE IF EXISTS `tb_core_role_menu`;
CREATE TABLE `tb_core_role_menu` (
  `id` bigint NOT NULL COMMENT '主键',
  `role_id` bigint NOT NULL COMMENT '角色ID',
  `menu_id` bigint NOT NULL COMMENT '菜单ID',
  `create_user` bigint NOT NULL DEFAULT '1' COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint NOT NULL DEFAULT '1' COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` bigint NOT NULL DEFAULT '0' COMMENT '删除时间',
  `create_org` bigint DEFAULT NULL COMMENT '创建部门',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `menu_role_id_fk` (`role_id`) USING BTREE,
  KEY `role_menu_menu_id_fk` (`menu_id`) USING BTREE,
  CONSTRAINT `menu_role_id_fk` FOREIGN KEY (`role_id`) REFERENCES `tb_core_role` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `role_menu_menu_id_fk` FOREIGN KEY (`menu_id`) REFERENCES `tb_core_top_menu` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='角色顶级菜单关联表';

